form[aria-label="Restaurant Suggestion Form"] {
  background: var(--card);
  border-radius: 18px;
  box-shadow: var(--shadow-strong);
  padding: 38px 30px 32px 30px;
  margin: 38px auto 0 auto;
  border: 1.5px solid var(--border-color);
  max-width: 540px;
}

form[aria-label="Restaurant Suggestion Form"] input,
form[aria-label="Restaurant Suggestion Form"] select {
  background: rgba(255,255,255,0.04);
  border: 1.5px solid var(--border-color);
  color: var(--text-color);
  border-radius: 8px;
  font-size: 1.1rem;
  padding: 12px 14px;
  transition: border-color 0.18s;
  outline: none;
  box-shadow: none;
  margin-top: 0;
  margin-bottom: 0;
}
form[aria-label="Restaurant Suggestion Form"] input:focus,
form[aria-label="Restaurant Suggestion Form"] select:focus {
  border-color: var(--accent);
}


form[aria-label="Restaurant Suggestion Form"] label {
  color: var(--primary);
  font-weight: 600;
  margin-bottom: 2px;
  letter-spacing: 0.01em;
  font-family: 'Inter', Arial, sans-serif;
  font-size: 0.98em;
}

form[aria-label="Restaurant Suggestion Form"] .title {
  margin-bottom: 14px;
}

form[aria-label="Restaurant Suggestion Form"] .btn {
  margin-top: 14px;
}

form[aria-label="Restaurant Suggestion Form"] option {
  color: #222;
}

/* Recommendation Results Card */
[role="region"][aria-live="polite"] {
  margin-top: 44px;
  background: linear-gradient(93deg, rgba(76,175,80,0.08), rgba(255,193,7,0.10) 60%, rgba(255,87,34,0.09));
  border-radius: 16px;
  min-height: 110px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-secondary);
  font-size: 1.21rem;
  border: 1.5px solid var(--border-color);
  box-shadow: var(--shadow-soft);
}

::-webkit-scrollbar-thumb {
  background: var(--primary);
  border-radius: 11px;
}
::-webkit-scrollbar {
  width: 9px;
  background: var(--surface);
}

